import React, {useEffect, useState, useCallback} from 'react';
import axios from 'axios';
import './App.css';

import Header from './Header';
function App() { 

  const [city, setCity] = useState('')
  const[weatherData, setWeatherData] = useState(null)

  const fetchData = useCallback(async () => {
  try{
    const response = axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=a8eb5aa64568880f32d4b8f8d32e1a9d`);
    setWeatherData(response.data)
  }

  catch(error){
    console.error(error);
  }

}, [city]);


useEffect(() =>{
  fetchData();
}, [fetchData]);


const handleInputChange = (e) =>{
setCity(e.target.value);
}


return(
  <div>
    <form>
      <input type="text" placeholder="Enter City Name" value={city} onChange={handleInputChange}/>
    </form>

    {weatherData ? (
      <>
       <Header CityName={city} Temperature={weatherData.main.temp} HighTemp={weatherData.main.temp_max} LowTemp={weatherData.main.temp_min} Description={weatherData.weather[0].description}/>
      </>
    ) :
    (
      <p>Loading weather data...</p>
    )
    }

  </div>
)};
export default App;
